@List.getElem?_modify : ∀ {α : Type u_1} (f : α → α) (i : Nat) (l : List α) (j : Nat),
  (l.modify i f)[j]? = (fun a => if i = j then f a else a) <$> l[j]?
@List.getElem?_map : ∀ {α : Type u_1} {β : Type u_2} {f : α → β} {l : List α} {i : Nat},
  (List.map f l)[i]? = Option.map f l[i]?
@List.length_modify : ∀ {α : Type u_1} (f : α → α) (l : List α) (i : Nat), (l.modify i f).length = l.length
@List.Sublist.append : ∀ {α : Type u_1} {l₁ l₂ r₁ r₂ : List α},
  l₁.Sublist l₂ → r₁.Sublist r₂ → (l₁ ++ r₁).Sublist (l₂ ++ r₂)
@List.getElem?_modify_eq : ∀ {α : Type u_1} (f : α → α) (i : Nat) (l : List α), (l.modify i f)[i]? = f <$> l[i]?
@List.getElem?_modify_ne : ∀ {α : Type u_1} (f : α → α) {i j : Nat} (l : List α), i ≠ j → (l.modify i f)[j]? = l[j]?
